window.MeasurementLabSpecs=[{"id":"beam-smearing","chapter":11,"anchor":"components","title":"谱线变宽，可能来自未分辨的旋转","eyebrow":"空间混合 · 局部观测模型","intro":"让一条具有线性视向速度梯度的盘穿过高斯点扩散函数和有限提取孔径。比较真实混合线型与具有相同二阶矩的高斯，分清随机运动与未分辨的有序运动。","params":[{"key":"dispersion","label":"本征速度弥散 σ₀（km/s）","min":10,"max":100,"step":1,"value":30},{"key":"gradient","label":"局部速度梯度 g（km/s/kpc）","min":-150,"max":150,"step":5,"value":80},{"key":"seeing","label":"PSF 半高全宽 b（kpc）","min":0,"max":3,"step":0.05,"value":1},{"key":"aperture","label":"提取孔径宽 w（kpc）","min":0,"max":3,"step":0.05,"value":1}],"values":["混合线型的 σeff（km/s）","空间模糊贡献 σPSF（km/s）","孔径贡献 σap（km/s）","σeff / σ₀"],"formulaTex":["v(x)=v_0+g x,\\quad s=\\frac b{2\\sqrt{2\\ln2}}","\\sigma_{\\rm eff}^2=\\sigma_0^2+(g s)^2+\\frac{g^2w^2}{12}","s_v^2=\\sigma_0^2+(g s)^2,\\quad a=\\frac{|g|w}{2}","p(v)=\\frac{\\Phi((v+a)/s_v)-\\Phi((v-a)/s_v)}{2a}\\quad(a>0)","a=0:\\quad p(v)=\\frac{e^{-v^2/(2s_v^2)}}{\\sqrt{2\\pi}s_v}"],"assumptions":"一维局部模型；光度面密度恒定、速度梯度线性、本征线型高斯、平移不变的高斯PSF，随后在均匀权重矩形孔径中提取。v 为相对孔径中心平均速度 v₀ 的偏移。二阶矩的方差相加在此精确；有限孔径时线型一般不是高斯，不能把 2.355σeff 自动称为真实FWHM。没有仪器谱向展宽、噪声、亮度梯度、盘边缘或完整二维投影。w=0 是单位通量归一的无限小孔径极限，不能据此推断实际光子数。b=0 是理想无空间模糊极限。","pages":[499,501],"source":"MBW §11.1.2 pp.499–501 的盘运动与有限分辨率背景；PSF与孔径卷积为网页新增教学推导。","references":[["Davies 等 (2011)：未分辨速度梯度","https://arxiv.org/abs/1108.0285"],["Graham 等 (2018)：亮度加权矩与PSF","https://academic.oup.com/mnras/article/477/4/4711/4919618"]]},{"id":"line-spread","chapter":13,"anchor":"structure","title":"从谱线宽度中，分离恒星与仪器","eyebrow":"Anatomy · 谱线读出实验台","intro":"同一条吸收线会被恒星运动和仪器响应共同展宽。扫描谱线，观察宽度增加而缺额积分守恒，再改变仪器校准，检查反演什么时候失去物理解。","params":[{"key":"stars","label":"恒星视向速度弥散 σ★（km/s）","min":0,"max":350,"step":5,"value":150},{"key":"template","label":"静止模板线宽 σtpl（km/s）","min":10,"max":60,"step":1,"value":20},{"key":"resolution","label":"光谱分辨本领 ℛ","min":800,"max":12000,"step":100,"value":3000},{"key":"calibration","label":"采用 / 真实仪器宽度 k","min":0.8,"max":1.2,"step":0.01,"value":1},{"key":"sample","label":"读取位置 u = v / σobs","min":-4,"max":4,"step":0.05,"value":0}],"values":["仪器 σinst（km/s）","总线宽 σobs（km/s）","反演 σrec（km/s）","所选位置的归一化通量","缺额积分 Wv（km/s）","总线半高全宽（km/s）"],"formulaTex":["\\mathcal R=\\frac{\\lambda}{\\Delta\\lambda_{\\rm FWHM}},\\quad\\sigma_{\\rm inst}=\\frac{c}{2\\sqrt{2\\ln2}\\,\\mathcal R}","\\sigma_{\\rm pre}^2=\\sigma_\\star^2+\\sigma_{\\rm tpl}^2,\\quad\\sigma_{\\rm obs}^2=\\sigma_{\\rm pre}^2+\\sigma_{\\rm inst}^2","F(v)=1-\\frac{W_v}{\\sqrt{2\\pi}\\sigma_{\\rm obs}}e^{-v^2/(2\\sigma_{\\rm obs}^2)},\\quad W_v=20\\,\\mathrm{km\\,s^{-1}}","\\sigma_{\\rm cal}=k\\sigma_{\\rm inst},\\quad\\sigma_{\\rm rec}^2=\\sigma_{\\rm obs}^2-\\sigma_{\\rm tpl}^2-\\sigma_{\\rm cal}^2","v=u\\sigma_{\\rm obs},\\quad\\int[1-F(v)]\\,dv=W_v"],"assumptions":"三种独立高斯卷积：静止恒星模板吸收缺额、光度加权LOSVD、仪器LSF。谱线坐标是一阶Doppler速度；这里不处理宇宙学红移、混线、非高斯LOSVD、噪声或多条谱线拟合。ℛ 以仪器线扩展函数的FWHM定义。Wv 是速度坐标中的缺额积分，固定为20 km/s，当前参数保证通量非负；不是以波长为单位的等效宽度。校准系数 k 只影响反演，不改变已经生成的观测谱线。负反演方差表示这套输入与校准不相容，不截断成零；恰为零是模型的形式边界，不能作为真实观测的零弥散证据。Anatomy装置只示意谱向扫描读数，结构位置与扫描动效不编码真实光速或完整望远镜光学。","pages":[575,576],"source":"MBW §13.1.1 pp.575–576，LOSVD及吸收线观测；高斯卷积与校准反演为网页新增教学推导。","references":[["ESO：按FWHM定义分辨率","https://www.eso.org/observing/dfo/quality/UVES/qc/resolution_qc1.html"],["Cappellari (2017)：LOSVD卷积","https://arxiv.org/abs/1607.08538"]]}];
